package com.habitpro.model;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.util.*;@Document("habits")public class Habit{@Id private String id;private String name,category,userId;private List<String> completedDates=new ArrayList<>();private int streak;public String getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getUserId(){return userId;}public void setUserId(String v){userId=v;}public List<String> getCompletedDates(){return completedDates;}public void setCompletedDates(List<String> v){completedDates=v;}public int getStreak(){return streak;}public void setStreak(int v){streak=v;}}